SELECT t_product_class.parent_id AS id, COUNT(t_product_class.parent_id) AS count FROM t_product_class WHERE t_product_class.is_deleted = 0 AND t_product_class.parent_id IN
#{id}
AND t_product_class.id != #{param.notId}
GROUP BY t_product_class.parent_id

SELECT t_product_class.id, t_product_class.status AS status, t_product_class.product_class_no AS productClassNo, t_product_class.product_class_name AS productClassName, t_product_class.product_class_orders AS productClassOrders, t_product_class.main_or_byproduct AS mainOrByproduct, t_product_class.is_whp AS isWhp, t_product_class.parent_id AS parentId FROM t_product_class WHERE t_product_class.is_deleted = 0 AND t_product_class.parent_id = #{parentId}
AND t_product_class.product_class_name like CONCAT('%', #{productClassName}, '%')
AND t_product_class.status = #{status}

